    constructor() { 
        this.children = new Map(); 
        this.isEnd = false; 
    } 
}; 

// Build trie tree from cities dataframe
let root = new TrieNode(); 
const cities_df = [place list of cities here]

for (let i=0; i < cities_df.length; i++) { 
    let word = cities_df[i]; 
    let currentNode = root; 

    for (let j = 0; j < word.length; j++) { 
        let ch = word[j]; 

        if (!currentNode.children.has(ch)) { 
            let node = new TrieNode(); 
            currentNode.children.set(ch, node); 
        } 

        currentNode = currentNode.children.get(ch); 
    } 

    // mark currentNode end of word 
    currentNode.isEnd = true; 
} 

// Define autocomplete function
function suggestCities(ch) { 
    let currentNode = root; 

    for (let i = 0; i < ch.length; i++) { 
        let c = ch[i]; 

        if (currentNode.children.has(c)) { 
            currentNode = currentNode.children.get(c); 
        } 
        else { 
            return []; 
        } 
    } 

    let suggestions = []; 

    traverse(currentNode, ch, suggestions); 

    return suggestions; 
} 

function traverse(node, ch, arr) { 

    if (node.isEnd) { 
        arr.push(ch); 
    } 

    for (let letter of node.children.keys()) { 

        traverse(node.children.get(letter), 
            ch + letter, arr); 
    } 
}
