        return stop_words.count(word) > 0;
    }), words.end());
}

// Function to build a frequency table of words in the input text
unordered_map<string, int> build_frequency_table(string text, unordered_set<string>& stop_words) {
    unordered_map<string, int> frequency_table;
    vector<string> words = split_words(preprocess(text));
    remove_stop_words(words, stop_words);
    for (auto word : words) {
        frequency_table[word]++;
    }
    return frequency_table;
}

// Function to calculate the cosine similarity between two vectors
double cosine_similarity(unordered_map<string, int>& v1, unordered_map<string, int>& v2) {
    double dot_product = 0;
    double v1_norm = 0;
    double v2_norm = 0;
    for (auto p1 : v1) {
        if (v2.count(p1.first) > 0) {
            dot_product += p1.second * v2[p1.first];
