import numpy as np
def luDecomp(A, b):
    # Perform LU decomposition on the matrix A and solve the system of linear
    # equations Ax = b using forward and backward substitution.

    n = A.shape[0]
    L = np.eye(n)
    U = A.copy()
    for k in range(n-1):
        for i in range(k+1, n):
            factor = U[i,k] / U[k,k]
            L[i,k] = factor
            U[i,k:n] -= factor * U[k,k:n]

    y = forwardSub(L, b)
    x = backSub(U, y)

    return L, U, x
def forwardSub(L, b):
    # Perform forward substitution on the lower triangular matrix L
    # and the right-hand side vector b to solve the system Ly = b.

    n = len(b)
    y = np.zeros(n)
    for i in range(n):
        y[i] = (b[i] - np.dot(L[i,:i], y[:i])) / L[i,i]

    return y
def backSub(U, b):
    # Perform back substitution on the upper triangular matrix U
    # and the right-hand side vector b to solve the system Ux = b.

    n = len(b)
    x = np.zeros(n)
    for i in range(n-1, -1, -1):
        x[i] = (b[i] - np.dot(U[i,i+1:], x[i+1:])) / U[i,i]

    return x
